import React, { useRef, useState } from 'react';
import { motion } from 'framer-motion';
import { ArrowRight } from 'lucide-react';
import { GithubIcon } from '../common/Icons';
import { CleanProject } from '../../data/projects';

interface ProjectCardProps {
  project: CleanProject;
  index: number;
  prominent?: boolean;
}

// Project Window Frame with Real Screenshot
const ProjectPreviewWindow: React.FC<{
  title: string;
  imageUrl?: string;
}> = ({ title, imageUrl }) => {
  return (
    <div className="relative w-full aspect-[16/10] bg-[#070707] rounded-xl overflow-hidden border border-neutral-800/80 group-hover:border-red-950 transition-colors flex flex-col">
      {/* Application Window Titlebar */}
      <div className="h-7 bg-[#0E0E0E] border-b border-neutral-800/60 px-3 flex items-center justify-between flex-shrink-0 z-10">
        <div className="flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-neutral-700" />
          <span className="w-2 h-2 rounded-full bg-neutral-700" />
          <span className="w-2 h-2 rounded-full bg-neutral-700" />
        </div>
        <span className="font-mono text-[10px] text-neutral-500 uppercase tracking-widest truncate max-w-[160px]">
