        </span>
        <span className="w-1.5 h-1.5 rounded-full bg-[#E50914] animate-pulse" />
      </div>

      {/* Screen Visual — Real Project Screenshot */}
      <div className="relative flex-1 overflow-hidden group/screen bg-[#050505]">
        {imageUrl ? (
          <img
