        ) : (
          <div className="w-full h-full flex items-center justify-center bg-[#0C0C0C]">
            <span className="font-mono text-xs text-neutral-500">{title}</span>
          </div>
        )}
        {/* Ambient Dark Gradient Vignette for Seamless Card Blend */}
        <div className="absolute inset-0 bg-gradient-to-t from-[#0A0A0A] via-black/10 to-transparent pointer-events-none" />
        <div className="absolute inset-0 border border-red-500/0 group-hover:border-red-600/30 transition-colors pointer-events-none" />
      </div>
    </div>
  );
};

export const ProjectCard: React.FC<ProjectCardProps> = ({ project, index, prominent = false }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [rotate, setRotate] = useState({ x: 0, y: 0 });
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [isHovered, setIsHovered] = useState(false);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    // Controlled 3D perspective tilt
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const rotateX = ((y - centerY) / centerY) * (prominent ? -5 : -7);
    const rotateY = ((x - centerX) / centerX) * (prominent ? 5 : 7);
    setRotate({ x: rotateX, y: rotateY });
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    setRotate({ x: 0, y: 0 });
  };

  // Requirement 8: Scroll reveal variations
  // NEXUS: reveals from slight left/depth
  // Hamara Commerce: reveals from slight right/depth
  // Lower projects: stagger upward one after another
  const getInitialMotion = () => {
    if (index === 0) return { opacity: 0, x: -35, rotateY: 5, rotateX: 2 };
    if (index === 1) return { opacity: 0, x: 35, rotateY: -5, rotateX: 2 };
    return { opacity: 0, y: 35, rotateX: 6, rotateY: 0 };
  };

  return (
    <motion.div
      ref={cardRef}
      initial={getInitialMotion()}
      whileInView={{ opacity: 1, x: 0, y: 0, rotateX: 0, rotateY: 0 }}
      viewport={{ once: true, margin: '-60px' }}
      transition={{ duration: 0.65, delay: index * 0.08, ease: 'easeOut' }}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={handleMouseLeave}
      style={{
        transformStyle: 'preserve-3d',
        transform: `perspective(1000px) rotateX(${rotate.x}deg) rotateY(${rotate.y}deg) translateZ(${isHovered ? 8 : 0}px)`,
        transition: isHovered ? 'none' : 'transform 0.4s ease-out',
      }}
      className={`group relative rounded-2xl bg-[#0A0A0A]/95 border transition-colors duration-300 flex flex-col justify-between overflow-hidden ${
        prominent
          ? 'border-red-900/50 hover:border-[#E50914] shadow-[0_15px_40px_rgba(0,0,0,0.85)] p-5 sm:p-6'
          : 'border-neutral-900/90 hover:border-red-900/50 p-5 sm:p-6 shadow-[0_10px_30px_rgba(0,0,0,0.7)]'
      }`}
    >
      {/* Cursor Follow Red Light Glow */}
      <div
        className="pointer-events-none absolute -inset-px transition-opacity duration-300"
        style={{
          opacity: isHovered ? 1 : 0,
          background: `radial-gradient(350px circle at ${mousePos.x}px ${mousePos.y}px, rgba(229, 9, 20, 0.15), transparent 70%)`,
        }}
      />

      {/* Top Red Glow Accent on prominent cards */}
      {prominent && (
        <div className="absolute top-0 inset-x-0 h-[2px] bg-gradient-to-r from-transparent via-[#E50914] to-transparent opacity-70 group-hover:opacity-100 transition-opacity" />
      )}

      <div>
        {/* Screenshot / Preview Window at Top */}
        <div className="mb-5 transition-transform duration-300 group-hover:scale-[1.01]">
          <ProjectPreviewWindow
            title={project.title}
            imageUrl={project.imageUrl}
          />
        </div>

        {/* Project Title (Natural Case) */}
        <h3 className="font-heading font-bold text-xl sm:text-2xl text-white group-hover:text-[#E50914] transition-colors">
          {project.title}
        </h3>

        {/* Tech Stack Pills right below Title matching full-structure.png */}
        <div className="flex flex-wrap gap-1.5 mt-2.5">
          {project.tags.map((tag) => (
            <span
              key={tag}
              className="px-2.5 py-0.5 rounded bg-[#121212] border border-neutral-800/80 font-sans text-[11px] text-neutral-300 font-medium"
            >
              {tag}
            </span>
          ))}
        </div>

        {/* Short Description */}
        <p className="mt-3 font-sans text-xs sm:text-sm text-neutral-300 leading-relaxed line-clamp-3">
          {project.shortDescription}
        </p>
      </div>

      {/* Footer: Action Buttons matching full-structure.png */}
      <div className="mt-6 pt-4 border-t border-neutral-900/90 flex items-center gap-2.5">
        {project.liveUrl ? (
          <a
            href={project.liveUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-[#E50914] text-white font-sans font-semibold text-xs uppercase tracking-wider shadow-[0_0_15px_rgba(229,9,20,0.35)] hover:shadow-[0_0_25px_rgba(229,9,20,0.6)] hover:bg-[#ff1e2b] transition-all active:scale-[0.98]"
          >
            <span>Live Demo</span>
            <ArrowRight className="w-3.5 h-3.5" />
          </a>
        ) : (
          <a
            href={project.githubUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-[#E50914] text-white font-sans font-semibold text-xs uppercase tracking-wider shadow-[0_0_15px_rgba(229,9,20,0.35)] hover:shadow-[0_0_25px_rgba(229,9,20,0.6)] hover:bg-[#ff1e2b] transition-all active:scale-[0.98]"
          >
            <span>View Repo</span>
            <ArrowRight className="w-3.5 h-3.5" />
          </a>
        )}

        <a
          href={project.githubUrl}
          target="_blank"
          rel="noopener noreferrer"
          aria-label="View on GitHub"
          className="inline-flex items-center justify-center p-2.5 rounded-xl bg-[#111111] text-neutral-300 border border-neutral-800 hover:border-red-600/60 hover:text-white hover:bg-[#181818] transition-all"
        >
          <GithubIcon size={16} className="text-[#E50914]" />
        </a>
      </div>
    </motion.div>
  );
};

